 "1rvx78ls63x": "angle de la liaison (la variable d'une liaison R)",
 "29mgu1qu8a9": "<strong><i>d</i><sub>i</sub></strong>",
 "21eg4ea4fpq": "<strong>le long de</strong> <i>z</i><sub>i−1</sub>",
 "2fkv6kygnbo": "décalage (la variable d'une liaison P)",
